import{z as i,x as n,o as e,c as s,q as B,j as t,D as a,d as A,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"成本工程收束","description":"","frontmatter":{"title":"成本工程收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-map.md","filePath":"llm/ce-map.md","lastUpdated":1791413859000}'),c={name:"llm/ce-map.md"};function m(h,E,p,d,D,C){const l=n("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="成本工程收束" tabindex="-1">成本工程收束 <a class="header-anchor" href="#成本工程收束" aria-label="Permalink to &quot;成本工程收束&quot;">​</a></h1><div class="epigraph"><p>成本工程的全部产出是一张账：拆得开组成，钉得死口径，拿得动杠杆，守得住合同。</p><footer>—— 据本课程各课与 Pope et al., 2022 等口径收束</footer></div><p><a href="/llm/ce-cost-quality-contract">上一课</a>把成本与质量钉成可执行的合同条款，本课程到此收束。十三课合成一张地图、一条主线、一份决策单；收束的任务不是新知识，是检索——面对一句「太贵了」，按什么次序打开哪些旋钮。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成本工程的知识散在口径、杠杆、治理三层，临时抱佛脚的用法是记住几个「省钱技巧」：技巧不可迁移，画像一换就失效。缺口是把课程收成一套可执行的次序，让「太贵了」变成一个有流程的诊断，而不是一轮拍脑袋的降配。</p><p><span class="marginnote">直觉类比：「太贵了」的排查像医生问诊：先量体温血压（钉口径），再问病史与作息（流量形状、调用结构），最后才考虑动手术（换模型、砍服务）。上来就开刀的省钱，多数是在治一场误诊。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="地图" tabindex="-1">地图 <a class="header-anchor" href="#地图" aria-label="Permalink to &quot;地图&quot;">​</a></h3><p>三单元各司其职。构成单元（<a href="/llm/ce-cost-components">成本的组成与口径</a>、<a href="/llm/ce-per-million-benchmarks">每百万 token 的基准</a>、<a href="/llm/ce-batch-economics">批大小的经济学</a>）给语言：四笔账、三种口径、单价函数——没有这套语言，后面的杠杆连「省了什么」都说不清。优化杠杆单元（<a href="/llm/ce-cache-economics">缓存命中经济学</a>、<a href="/llm/ce-routing-cost">路由的成本面</a>、<a href="/llm/ce-cascade-cost">模型级联的成本</a>、<a href="/llm/ce-quantization-savings">量化省下什么</a>、<a href="/llm/ce-reserved-vs-spot">租用对比：预留与竞价</a>）给旋钮：改请求形状、改单价谱、改字节、改买法。治理单元（<a href="/llm/ce-cost-observability">成本观测</a>、<a href="/llm/ce-budget-alerting">预算与告警</a>、<a href="/llm/ce-unit-economics-case">单位经济案例</a>、<a href="/llm/ce-optimization-cases">优化案例研究</a>、<a href="/llm/ce-cost-quality-contract">成本与质量的合同</a>）给执行：仪表、约束、账本、纪律与条款。</p>',9)),(e(),t(o,null,{default:a(()=>[r(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E6%9E%84%E6%88%90%EF%BC%9A%E5%9B%9B%E7%AC%94%E8%B4%A6%E4%B8%8E%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20F2%5B%22%E5%9F%BA%E5%87%86%EF%BC%9A%E7%94%BB%E5%83%8F%E5%8A%A0%E6%9D%83%E5%8D%95%E4%BB%B7%22%5D%20--%3E%20F3%5B%22%E6%89%B9%EF%BC%9A%E5%8D%95%E4%BB%B7%E5%87%BD%E6%95%B0%E4%B8%8E%E5%B7%A5%E4%BD%9C%E7%82%B9%22%5D%0A%20%20F3%20--%3E%20L1%5B%22%E6%9D%A0%E6%9D%86%EF%BC%9A%E7%BC%93%E5%AD%98%E2%80%94%E2%80%94%E8%AF%B7%E6%B1%82%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E8%B7%AF%E7%94%B1%E4%B8%8E%E7%BA%A7%E8%81%94%E2%80%94%E2%80%94%E5%8D%95%E4%BB%B7%E8%B0%B1%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E9%87%8F%E5%8C%96%E2%80%94%E2%80%94%E5%AD%97%E8%8A%82%22%5D%0A%20%20L3%20--%3E%20L4%5B%22%E7%A7%9F%E6%B3%95%E2%80%94%E2%80%94%E4%B9%B0%E5%BE%97%E7%9C%81%22%5D%0A%20%20L4%20--%3E%20G1%5B%22%E6%B2%BB%E7%90%86%EF%BC%9A%E8%A7%82%E6%B5%8B%E4%B8%8E%E9%A2%84%E7%AE%97%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E5%8D%95%E4%BD%8D%E8%B4%A6%E4%B8%8E%E6%A1%88%E4%BE%8B%E7%BA%AA%E5%BE%8B%22%5D%0A%20%20G2%20--%3E%20G3%5B%22%E5%90%88%E5%90%8C%EF%BC%9A%E8%B4%A8%E9%87%8F%E9%97%A8%E7%A6%81%E4%B8%8E%E5%9B%9E%E6%BB%9A%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h3 id="决策单" tabindex="-1">决策单 <a class="header-anchor" href="#决策单" aria-label="Permalink to &quot;决策单&quot;">​</a></h3><p>按数量级排的八问：一问口径——混报了吗，先把四笔账与测量窗口钉死；二问形状——重复多少，缓存的上界在哪；三问谱系——难度方差够不够支撑路由与级联；四问字节——量化空间与误差预算各剩多少；五问打满——批工作点离 SLO 上限还有多远；六问买法——负载按可中断性分层了吗；七问账目——单位账里漏了哪些小项；八问合同——门禁与回滚线写下来了吗。次序是刻意的：前两问不花钱就能排除一半误诊，中间四问按作用账目从结构到系数，后两问保证省下来的钱留得住。</p><p><span class="marginnote">数字实例：口径混报能把「成本」虚报一倍不止——时租 24 美元/天的卡，高峰日跑 400 万 token 时「单价 6 美元/百万」，低谷日跑 100 万时变 24 美元/百万。把测量窗口钉死后再看，模型可能根本没变贵：这就是前两问不花一分钱就能排除的误诊。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主线的原理只有一条：先给口径再给杠杆。没有口径的杠杆是玄学——省了说不清省在哪；没有杠杆的口径是抱怨——账拆得再细也不省钱。排序永远数量级优先（结构先于系数），验证永远三列表（成本、延迟、质量同看），这是贯穿构成、杠杆、治理三单元的同一副骨架。与邻域的接口也交代清楚：上游承接<a href="/llm/lc-memory-account">显存·时间积</a>的会计口径与调度侧的打满率语言；下游开口给 <a href="/llm/agent-cost-latency">Agent 的成本与延迟</a>、<a href="/llm/rag-latency-cost">RAG 的延迟与成本</a>与<a href="/llm/mm-cost-capacity">多模态的容量规划</a>——本课程给它们共同的记账语言，各自的画像与杠杆留在各自课程。</p>',5)),(e(),t(o,null,{default:a(()=>[r(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20UP1%5B%22%E4%B8%8A%E6%B8%B8%EF%BC%9A%E6%98%BE%E5%AD%98%C2%B7%E6%97%B6%E9%97%B4%E7%A7%AF%E7%9A%84%E4%BC%9A%E8%AE%A1%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20CE%5B%22%E6%88%90%E6%9C%AC%E5%B7%A5%E7%A8%8B%EF%BC%9A%E5%85%B1%E5%90%8C%E7%9A%84%E8%AE%B0%E8%B4%A6%E8%AF%AD%E8%A8%80%22%5D%0A%20%20UP2%5B%22%E4%B8%8A%E6%B8%B8%EF%BC%9A%E8%B0%83%E5%BA%A6%E4%BE%A7%E7%9A%84%E6%89%93%E6%BB%A1%E7%8E%87%22%5D%20--%3E%20CE%0A%20%20CE%20--%3E%20L1%5B%22%E6%9E%84%E6%88%90%EF%BC%9A%E8%B4%A6%E4%B8%8E%E5%8F%A3%E5%BE%84%22%5D%0A%20%20CE%20--%3E%20L2%5B%22%E6%9D%A0%E6%9D%86%EF%BC%9A%E5%BD%A2%E7%8A%B6%2F%E8%B0%B1%E7%B3%BB%2F%E5%AD%97%E8%8A%82%2F%E4%B9%B0%E6%B3%95%22%5D%0A%20%20CE%20--%3E%20L3%5B%22%E6%B2%BB%E7%90%86%EF%BC%9A%E8%A7%82%E6%B5%8B%2F%E9%A2%84%E7%AE%97%2F%E5%90%88%E5%90%8C%22%5D%0A%20%20CE%20--%3E%20D1%5B%22%E4%B8%8B%E6%B8%B8%EF%BC%9AAgent%20%E6%88%90%E6%9C%AC%E4%B8%8E%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20CE%20--%3E%20D2%5B%22%E4%B8%8B%E6%B8%B8%EF%BC%9ARAG%20%E5%BB%B6%E8%BF%9F%E4%B8%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20CE%20--%3E%20D3%5B%22%E4%B8%8B%E6%B8%B8%EF%BC%9A%E5%A4%9A%E6%A8%A1%E6%80%81%E5%AE%B9%E9%87%8F%E8%A7%84%E5%88%92%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">决策单的第一问常被跳过，也最常翻案：多起「模型太贵」的诊断，最后落在口径混报——时租除以波动流量得到的伪单价。先问口径再问模型，一半的成本会议可以不开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本工程不改变范式：架构换代（新注意力、新硬件、新计费模式）会重开账本，四笔账的科目要重审——但拆账、钉口径、排序验证的方法不随范式过期。价格长期下行不豁免工程：单价的绝对值是市场给的，单价的相对结构是工程挣的，同一模型上省一半的结构性成本，在任何价格水平上都成立。最后，这门课管的住成本，管不了价值：单位账算完，若毛利仍为负，那是产品问题——成本工程到此收束，不再向前一步。</p><p><span class="marginnote">常见误区：初学者容易拿「模型价格一直在降」当不做成本工程的理由。市场价格决定单价的绝对值，工程决定单价的相对结构——同一模型上省下的一半结构性成本，在价格再降时依然存在。省的是结构，不是赌行情。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三单元一线：构成给语言（账与口径），杠杆给旋钮（形状、谱系、字节、买法），治理给执行（仪表、预算、账本、合同）。</li><li>决策单八问按数量级排：口径、形状、谱系、字节、打满、买法、账目、合同。</li><li>先口径后杠杆，先结构后系数，验证永远成本、延迟、质量三列同看。</li><li>与邻域共享记账语言：上游显存账与打满率，下游 Agent、RAG、多模态各自展开。</li><li>出处：口径框架据 Pope et al., 2022 与本仓库 KV 成本模型、服务成本模型各课；本课程各课为杠杆与治理的详细出处。</li></ul>',6))])}const _=i(c,[["render",m]]);export{F as __pageData,_ as default};
